            subtitle="Near-universal diabetes cover vs partial obesity cover"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={indicationBars}
                  margin={{ left: 8, right: 8, top: 8, bottom: 48 }}
