                    interval={0}
                    angle={-18}
                    textAnchor="end"
                    height={60}
                    tick={{ fill: SLATE, fontSize: 10 }}
                  />
                  <YAxis
                    domain={[0, 100]}
                    tick={{ fill: SLATE, fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
