"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  Pie,
  PieChart,
  ResponsiveContainer,
  XAxis,
  YAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  COST_IMPACT,
  COVERAGE_BY_YEAR,
  HEADLINE,
  INDICATION_CONTRAST,
  PHARMACY_TREND,
  SIZE_LADDER,
  SOURCE_NOTE,
  SPEND_INCREASE_SPLIT,
  fmt1,
  fmtPct,
  type FirmSizeBucket,
} from "@/data/employer-coverage-of-glp-1-weight-loss-drugs-2026-data";

// viz-types: size ladder bars, coverage YoY grouped bars, pharmacy composed
// (area+line), cost-impact horizontal bars, indication contrast + pie |
// layout: default | controls: view + survey + size bucket

type ViewId = "coverage" | "pharmacy" | "cost" | "indication";
type SurveyFilter = "all" | "kff" | "mercer";

const NAVY = "#0f172a";
const TEAL = "#0d9488";
const AMBER = "#d97706";
const ROSE = "#e11d48";
const SLATE = "#64748b";
const INDIGO = "#4f46e5";
const SKY = "#0284c8";

const BUCKET_OPTIONS: { id: FirmSizeBucket; label: string }[] = [
  { id: "kff_200_plus", label: "KFF 200+" },
  { id: "kff_5000_plus", label: "KFF 5k+" },
  { id: "mercer_500_plus", label: "Mercer 500+" },
  { id: "mercer_20000_plus", label: "Mercer 20k+" },
];

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
